<template>
  <v-card variant="outlined" class="mb-4">
    <v-card-title class="d-flex align-center"><v-icon class="me-2">mdi-source-branch</v-icon>Интерактивное добавление в виртуальные устройства<v-spacer/><v-btn size="small" variant="text" @click="$emit('close')">Закрыть режим</v-btn></v-card-title>
    <v-card-text>
      <v-alert type="info" variant="tonal" density="compact" class="mb-3">Выберите параметры на платах. Создаются виртуальные сущности, а не прямые HA-порты.</v-alert>
      <v-row><v-col cols="12" md="4"><v-text-field v-model="filter" label="Фильтр параметров" prepend-inner-icon="mdi-magnify" clearable density="compact"/></v-col><v-col cols="12" md="4"><v-text-field v-model="name" label="Имя виртуального устройства" density="compact"/></v-col><v-col cols="12" md="4"><TagsInput v-model="tags"/></v-col></v-row>
      <v-expansion-panels multiple><v-expansion-panel v-for="board in boards" :key="board.deviceId"><v-expansion-panel-title><v-checkbox-btn :model-value="isBoardSelected(board)" @click.stop="toggleBoard(board)"/><span>{{ board.deviceName }}</span><v-chip size="x-small" class="ms-2" :color="board.online ? 'success' : 'error'">{{ board.online ? 'online' : 'offline' }}</v-chip><v-chip size="x-small" class="ms-2">{{ selectedCount(board) }}/{{ board.ports.length }}</v-chip></v-expansion-panel-title><v-expansion-panel-text><v-list density="compact"><v-list-item v-for="port in filteredPorts(board)" :key="port.code"><template #prepend><v-checkbox-btn v-model="selected[`${board.deviceId}|${port.code}`]"/></template><v-list-item-title>{{ port.title || port.code }}</v-list-item-title><v-list-item-subtitle>{{ port.code }} · {{ port.kind || port.value_type || 'parameter' }}</v-list-item-subtitle><template #append><v-chip size="x-small" :color="port.virtual_status === 'used' ? 'success' : 'grey'">{{ port.virtual_status === 'used' ? 'используется' : 'свободен' }}</v-chip></template></v-list-item></v-list></v-expansion-panel-text></v-expansion-panel></v-expansion-panels>
      <div class="d-flex justify-end mt-4"><v-btn color="primary" :disabled="!selectedCodes.length || !name" :loading="loading" @click="createPreview">Сформировать конфигурацию</v-btn></div><v-alert v-if="message" :type="messageType" variant="tonal" class="mt-3">{{ message }}</v-alert>
    </v-card-text>
  </v-card>
  <v-dialog v-model="previewOpen" max-width="720" scrollable><v-card><v-card-title>Конфигурация виртуального устройства</v-card-title><v-card-text><v-alert type="warning" variant="tonal" class="mb-3">Физические HA-сущности не создаются. Проверьте виртуальную модель.</v-alert><div><b>{{ draft?.target?.name }}</b></div><div class="text-caption mb-2">Параметров: {{ draft?.ports?.length || 0 }}</div><v-list density="compact"><v-list-item v-for="port in draft?.ports || []" :key="port.physical_code"><v-list-item-title>{{ port.name }}</v-list-item-title><v-list-item-subtitle>{{ port.physical_code }} · {{ port.type }}</v-list-item-subtitle></v-list-item></v-list><div v-if="diff" class="text-caption mt-2">Добавится: {{ diff.ports_to_add?.length || 0 }}, уже существует: {{ diff.ports_existing?.length || 0 }}</div></v-card-text><v-card-actions><v-spacer/><v-btn variant="text" @click="previewOpen = false">Отмена</v-btn><v-btn color="primary" @click="apply(false)">Сохранить модель</v-btn><v-btn color="success" @click="apply(true)">Сохранить и опубликовать</v-btn></v-card-actions></v-card></v-dialog>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue'
import { secureFetch } from '@/services/fetch'
import TagsInput from '@/components/form_elements/TagsInput.vue'
const props = defineProps({ device: { type: Object, required: true } }); defineEmits(['close'])
const boards = ref([]); const selected = ref({}); const filter = ref(''); const name = ref(''); const tags = ref([]); const loading = ref(false); const message = ref(''); const messageType = ref('success'); const draft = ref(null); const diff = ref(null); const previewOpen = ref(false)
const selectedCodes = computed(() => Object.entries(selected.value).filter(([, value]) => value).map(([key]) => key))
const filteredPorts = board => board.ports.filter(port => !filter.value || `${port.title || ''} ${port.code}`.toLowerCase().includes(filter.value.toLowerCase()))
const selectedCount = board => board.ports.filter(port => selected.value[`${board.deviceId}|${port.code}`]).length
const isBoardSelected = board => selectedCount(board) === board.ports.length && board.ports.length > 0
const toggleBoard = board => { const value = !isBoardSelected(board); board.ports.forEach(port => { selected.value[`${board.deviceId}|${port.code}`] = value }) }
const load = async () => { boards.value = []; const device = props.device; try { const response = await secureFetch(`/api/myhome/device/${device.id}/ha/virtual-overview`); const data = await response.json(); boards.value.push({ deviceId: device.id, deviceName: device.name, online: device.online === true, ports: data.physical_ports || [] }) } catch { boards.value.push({ deviceId: device.id, deviceName: device.name, online: false, ports: [] }) } }
const createPreview = async () => { loading.value = true; try { const grouped = {}; selectedCodes.value.forEach(item => { const [deviceId, ...parts] = item.split('|'); (grouped[deviceId] ||= []).push(parts.join('|')) }); const first = Object.keys(grouped)[0]; let combined = null; for (const [deviceId, codes] of Object.entries(grouped)) { const response = await secureFetch(`/api/myhome/device/${deviceId}/ha/virtual-draft`, { method: 'POST', data: { source_type: 'port', selected_codes: codes, name: name.value, tags: (tags.value || []).map(item => String(item).trim().replace(/^#+/, '')).filter(Boolean) } }); const data = await response.json(); if (!combined) combined = data.draft; else combined.ports.push(...data.draft.ports) } draft.value = combined; const preview = await secureFetch(`/api/myhome/device/${first}/ha/virtual-draft/preview`, { method: 'POST', data: { draft: draft.value } }); diff.value = (await preview.json()).diff; previewOpen.value = true } catch { message.value = 'Не удалось сформировать конфигурацию'; messageType.value = 'error' } finally { loading.value = false } }
const apply = async publish => { const first = selectedCodes.value[0]?.split('|')[0]; await secureFetch(`/api/myhome/device/${first}/ha/virtual-draft/${publish ? 'publish' : 'apply'}`, { method: 'POST', data: { draft: draft.value, confirmed: true } }); previewOpen.value = false; message.value = publish ? 'Виртуальное устройство сохранено и опубликовано в HA' : 'Виртуальное устройство сохранено'; await load() }
onMounted(load)
</script>
